    # Use exponential moving average: weight recent observation 0.2, old reputation 0.8
    alpha = 0.2
    if observation['action'] == 'cooperate':
        target = 1.0
    else:
        target = -1.0
    new_rep = (1 - alpha) * current_reputation + alpha * target
    # Clamp to [-1, 1]
    return max(-1.0, min(1.0, new_rep))

